import sampleFemaleImg from '~/shared/assets/img/id_sample_female.png';
import sampleMaleImg from '~/shared/assets/img/passport_sample_male.png';
import { NativeFunction } from '~/shared/constants/native-function';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { PATHS } from '~/shared/routes/paths';

export const ChooseIDCardTypePage = () => {
  const { navigate } = useNavigate();

  const onClickIDCard = () => {
    window.webViewBridge.send(NativeFunction.IDScan, {
      success: () => {
        navigate(PATHS.issueWallet.confirm.IDCard);
      },
    });
  };

  const onClickPassport = () => {
    window.webViewBridge.send(NativeFunction.PassportScan, {
      success: () => {
        navigate(PATHS.issueWallet.confirm.passport);
      },
    });
  };

  const onClickDriveLicense = () => {
    window.webViewBridge.send(NativeFunction.IDScan, {
      success: () => {
        navigate(PATHS.issueWallet.confirm.driverLicense);
      },
    });
  };

  return (
    <div className="content">
      <div className="sub-step">
        <span>{i18n.t('step1')}</span>
        <span className="on">{i18n.t('step2')}</span>
        <span>{i18n.t('step2')}</span>
      </div>
      <div className="sub-desc">
        <p>{i18n.t('text:selectIDOrPassport')}</p>
      </div>
      <div className="sample-area">
        <p>{i18n.t('text:scanStartsAfterSelection')}</p>
        <div className="id-sample-area">
          <div className="id-sample-box">
            <div className="id-sample-img">
              <img src={sampleFemaleImg} alt={i18n.t('text:femaleIDCardExample')} />
            </div>
            <p>{i18n.t('text:idCardInfoExample')}</p>
          </div>
          <div className="id-sample-box">
            <div className="id-sample-img">
              <img src={sampleMaleImg} alt={i18n.t('text:malePassportExample')} />
            </div>
            <p>{i18n.t('text:passportInfoExample')}</p>
          </div>
        </div>
      </div>
      <div className="sel-wallet kyc-id">
        <div className="btn-col">
          <button type="button" className="app-btn" onClick={onClickIDCard}>
            {i18n.t('residentRegistrationCard')}
          </button>
          <button type="button" className="app-btn" onClick={onClickDriveLicense}>
            {i18n.t('driverLicense')}
          </button>
          <button type="button" className="app-btn" onClick={onClickPassport}>
            {i18n.t('passport')}
          </button>
        </div>
      </div>
    </div>
  );
};
